// Queue metadata is shared by Desktop and console servers; there is no separate CLI API.
const Q=(()=>{
 const terminal=new Set(['finished','rejected','failed','cancelled','deleted','deleting']);
 function prune(c){
  for(const name of ['generation_waiters','postprocess_waiters']){
   const seen=new Set();c[name]=(c[name]??[]).filter(w=>{
    if(!w||!w.owner)return false;
    let j=w.request_id&&S.valid(w.request_id)?S.get(w.request_id):null;
    if(!j&&S.valid(String(w.owner))){const index=S.read(S.root+'/executions/'+w.owner+'.json',null);if(index?.request_id&&S.valid(index.request_id))j=S.get(index.request_id);}
    // Unknown legacy entries remain blocked for reconciliation; never infer a dead worker by age.
    if(j&&(String(j.execution_id)!==String(w.owner)||j.cleared_at||j.cancel_requested||terminal.has(j.status)))return false;
    const key=String(w.owner);if(seen.has(key))return false;seen.add(key);return true;
   });
  }
 }
 function reason(c,stage){
  const boot=S.read('/files/.telegram-ui/comfy-boot.json',null);
  if(c.stop_pending)return {code:'stop_pending',detail:"Global cancellation is still in progress.",wake:false};
  if(boot?.boot_id&&(c.reconciled_boot!==boot.boot_id||c.reconciled_runtime!==RUNTIME))return {code:'restart_reconciliation',detail:"Comfy restarted: waiting for the supervisor to reconcile the saved queue.",wake:true};
  if(c.recovery_active)return {code:'recovery_active',detail:"Recovery in progress; waiting for the existing queue to finish.",wake:true};
  if(c.paused||c.lease?.blocked){
   // A positively identified closed/obsolete lease owner can request the ordinary safe recovery.
   // Recovery still fences workers and waits for two empty server snapshots before releasing it.
   const lease=c.lease,j=lease?.request_id&&S.valid(lease.request_id)?S.get(lease.request_id):null;
   const orphan=j&&(terminal.has(j.status)||j.cancel_requested||j.execution_id!==lease.owner);
   const marker=lease?JSON.stringify([lease.owner,lease.request_id,boot?.boot_id,RUNTIME]):null;
   if(orphan&&marker!==c.auto_recover_marker){c.recover_requested=true;c.auto_recover_marker=marker;}
   return {code:'admission_paused',detail:"Admission paused"+(lease?" by reservation "+lease.kind+" for "+lease.request_id:'')+". Check /status and /recover.",wake:!!orphan||c.recover_requested===true};
  }
  if(c.lease)return {code:'resource_reserved',detail:"Resource reserved for "+c.lease.kind+" of job "+c.lease.request_id+'.',wake:false};
  if(stage==='generation'&&c.postprocess_waiters.length)return {code:'postprocess_priority',detail:"Approved post-processing has priority to prevent memory overload.",wake:false};
  const first=(stage==='generation'?c.generation_waiters:c.postprocess_waiters)[0];
  if(first?.owner!==S.execution)return {code:'fifo',detail:"Waiting for earlier requests in the "+(stage==='generation'?"generation":"post-processing")+'.',wake:false};
  return null;
 }
 return {prune,reason};
})();

// Docker incarnation: a restart gets a new mutex namespace. Old empty locks are not stolen.
const RUNTIME=(()=>{const f=require('fs');try{
 const boot=f.readFileSync('/proc/sys/kernel/random/boot_id','utf8').trim();
 const stat=f.readFileSync('/proc/1/stat','utf8');const fields=stat.slice(stat.lastIndexOf(')')+2).split(' ');
 if(!/^[a-f0-9-]{36}$/.test(boot)||!/^\d+$/.test(fields[19]))throw Error();return boot+'-'+fields[19];
}catch(_){throw new Error('Recovery requires the configured Linux Docker container (/proc readable).');}})();

// Shared, embedded in Code nodes. Requires only built-in fs and shared /files.
const S = (() => {
  const fs=require('fs');
  const root='/files/.telegram-ui/scheduler', jobs=root+'/jobs', control=root+'/control.json';
  fs.mkdirSync(jobs,{recursive:true,mode:0o700});
  const execution=String($execution.id);
  const valid=id=>typeof id==='string'&&/^[A-Za-z0-9_-]{1,80}$/.test(id);
  const jobPath=id=>{if(!valid(id))throw new Error('Invalid request_id');return jobs+'/'+id+'.json';};
  const read=(p,fallback)=>fs.existsSync(p)?JSON.parse(fs.readFileSync(p,'utf8')):fallback;
  function write(p,value){
    const temp=p+'.tmp-'+execution+'-'+Date.now();let fd;
    try{fd=fs.openSync(temp,'wx',0o600);fs.writeFileSync(fd,JSON.stringify(value));fs.fsyncSync(fd);fs.closeSync(fd);fd=undefined;fs.renameSync(temp,p);}
    finally{if(fd!==undefined)fs.closeSync(fd);if(fs.existsSync(temp))fs.unlinkSync(temp);}
  }
  function tx(fn){
    let fd;try{fd=fs.openSync(control+'.lock-'+RUNTIME,'wx',0o600);}catch(e){if(e.code==='EEXIST')return {mutex_busy:true};throw e;}
    try{const c=read(control,{version:1,lease:null,generation_waiters:[],postprocess_waiters:[]});c.generation_waiters??=[];c.postprocess_waiters??=[];const result=fn(c);write(control,c);return result;}
    finally{fs.closeSync(fd);fs.unlinkSync(control+'.lock-'+RUNTIME);}
  }
  const get=id=>read(jobPath(id),null);
  const patch=(id,data)=>{const j=get(id);if(!j)throw new Error('Missing job '+id);const index=read(root+'/executions/'+execution+'.json',null);if(index?.request_id===id&&j.execution_id!==execution)throw new Error('Obsolete worker fenced by recovery.');if(j.cancel_requested&&execution===j.execution_id&&data.status&&data.status!=='deleted')data={...data,status:j.status};Object.assign(j,data,{updated_at:new Date().toISOString()});write(jobPath(id),j);return j;};
  function owned(c,kind){if(c.lease?.owner!==execution||c.lease?.kind!==kind||c.lease.blocked)throw new Error('Comfy reservation is absent or blocked; inspect scheduler before resubmitting.');}
  return {fs,root,jobs,execution,valid,jobPath,read,write,tx,get,patch,owned,control};
})();

const boot=S.read('/files/.telegram-ui/comfy-boot.json',null);
if(!boot?.boot_id)return [];
const result=S.tx(c=>{
 Q.prune(c);
 if(c.stop_pending)return {skip:true};
 const force=c.recover_requested===true;
 const changed=c.reconciled_boot!==boot.boot_id||c.reconciled_runtime!==RUNTIME;
 if(c.recovery_active){if(changed)c.recovery_active.idle_since=null;c.recover_requested=false;c.reconciled_boot=boot.boot_id;c.reconciled_runtime=RUNTIME;return {scan:true,boot_id:boot.boot_id};}
 if(!force&&!changed)return {scan:false};
 if(c.lease&&!/^tg-0-[0-9]+$/.test(c.lease.request_id??''))return {skip:true};
 const terminal=['finished','rejected','cancelled','deleted','deleting'];let count=0;
 const session=String(Date.now())+'-'+S.execution;
 const oldOwners=new Set();
 for(const n of S.fs.readdirSync(S.jobs).filter(n=>n.endsWith('.json'))){const j=S.read(S.jobs+'/'+n,null);
  if(!j||!/^tg-0-[0-9]+$/.test(j.request_id??'')||terminal.includes(j.status)||j.cleared_at||j.cancel_requested)continue;
  // A reported error is retried once after a restart, or on an explicit /recover.
  if(j.recovery?.boot_id===boot.boot_id&&j.recovery?.runtime===RUNTIME&&!force)continue;
  oldOwners.add(j.execution_id);
  const prior=j.recovery?.previous_status??j.status;
  S.patch(j.request_id,{execution_id:'recovering-'+session+'-'+count,status:'recovering',inflight:null,wait_reason:null,wait_detail:null,recovery_wake_error:null,history_poll:null,
   recovery:{ticket:session+'-'+count,previous_status:prior,previous_execution_id:j.execution_id,boot_id:boot.boot_id,runtime:RUNTIME,claimed:false},
   // Approval already obtained for the saved LTX video remains valid, not for a regenerated one.
   approved:j.approved===true||(c.lease?.kind==='postprocess'&&c.lease.request_id===j.request_id)||['waiting_postprocess','postprocess_waiting_for_idle','interpolating','upscaling'].includes(prior)});
  count++;
 }
 c.generation_waiters=c.generation_waiters.filter(w=>!oldOwners.has(w.owner));
 c.postprocess_waiters=c.postprocess_waiters.filter(w=>!oldOwners.has(w.owner));
 c.recover_requested=false;c.reconciled_boot=boot.boot_id;c.reconciled_runtime=RUNTIME;
 if(count||c.lease||c.paused){c.recovery_active={session,count,started_at:Date.now(),manual:force};c.paused=true;}
 else if(force)c.recovery_notice="No pending jobs to recover. Cancelled, rejected and completed jobs were preserved.";
 return {scan:!!c.recovery_active};
});
if(result.mutex_busy)return [];
return [{json:{...result,cleanup_key:S.fs.readFileSync('/files/.telegram-ui/comfy-control.key','utf8').trim()}}];

